SELECT 'gongkao', '工程量效率时间', 'kp-eng-b-qty-eff-time', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "工程量、效率与时间的基础关系"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "W (总量) = P (效率) × T (时间)。这是所有工程问题的万物起源。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目中直接给出某项工作的完成时间、每天完成的量，或者三者中已知两个求第三个。这是最基础的概念题，重点考察这三个变量的正反比关系。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式与推论"}]}, {"type": "katexBlock", "attrs": {"content": "W = P \\times T \\quad \\Rightarrow \\quad P = \\frac{W}{T} \\quad \\Rightarrow \\quad T = \\frac{W}{P}"}}, {"type": "paragraph", "content": [{"type": "text", "text": "重要推论（正反比）：", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "1. 当工作总量 W 一定时，效率 P 和时间 T 成【反比】。（干得越快，花的时间越少）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "2. 当时间 T 一定时，总量 W 和效率 P 成【正比】。（同样的时间，干得越快，出活越多）"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读题目找出已知变量] --> B{已知条件是具体数值还是比例?}\nB -- 具体数值 --> C[直接套用 W = P * T 求解第三个未知量]\nB -- 比例关系 --> D[利用正反比推论得出比例]\nD --> E[设份数(如 3x, 4x)代入求解]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 甲乙两人加工同样多的零件，甲的效率是乙的 1.5 倍。若乙加工这批零件需要 15 天，问甲需要几天？选项：A. 8  B. 10  C. 12  D. 15"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别：题目说了“加工同样多”，说明工作总量 W 一定。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "找比例：甲效率是乙的 1.5 倍，即 P甲 : P乙 = 3 : 2。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "正反比转化：因为 W 一定，时间 T 与效率 P 成反比。所以 T甲 : T乙 = 2 : 3。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "代入求解：已知 T乙 = 15 天，占 3 份，每份是 5 天。所以 T甲 = 2 份 = 10 天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：选 B。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "正反比颠倒：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "很多新手看到甲的效率高，算出乙需要15天，脑子一热直接 15 × 1.5 = 22.5天。记住，效率高的人花的时间必定更少！遇到反比，一定要在草稿纸上写下交叉相乘的比例。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "见到“一样多”、“同样工程”的字眼，条件反射写出“W恒定，P与T反比”。跳过求具体 W 的步骤，直接用比例秒杀。"}]}]}$$ AS jsonb), NULL, '工程量效率时间的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "工程量效率时间"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_b_qty_eff_time", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
